import{_ as t,a,b as n}from"./chunks/bubbles-03.CRJ58gUA.js";import{_ as o,o as r,c as s,a3 as i}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"Bubbles and input","description":"MiniTavern chat bubble and input styles — follow the theme, or set backgrounds, corners, narration / action / speech colors, and blur.","frontmatter":{"title":"Bubbles and input","description":"MiniTavern chat bubble and input styles — follow the theme, or set backgrounds, corners, narration / action / speech colors, and blur.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Bubbles and input · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern chat bubble and input styles — follow the theme, or set backgrounds, corners, narration / action / speech colors, and blur."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/manual/bubbles"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/manual/bubbles"}]]},"headers":[],"relativePath":"en/manual/bubbles.md","filePath":"en/manual/bubbles.md","lastUpdated":1791862671000}'),l={name:"en/manual/bubbles.md"};function u(h,e,c,d,b,p){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="bubbles-and-input" tabindex="-1">Bubbles and input <a class="header-anchor" href="#bubbles-and-input" aria-label="Permalink to &quot;Bubbles and input&quot;">​</a></h1><p>Path: bottom <strong>Settings</strong> → <strong>Chat settings</strong> → <strong>Bubbles and input</strong>.</p><p>This page changes chat appearance for the whole app. Theme and font size stay under <strong>Settings → Theme and font</strong>.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="Settings home"><figcaption>1 · Settings → Chat settings</figcaption></figure><figure class="shot-step"><img src="'+a+'" alt="Bubbles and input in chat settings"><figcaption>2 · Bubbles and input</figcaption></figure><figure class="shot-step"><img src="'+n+'" alt="Bubble colors and corner radius"><figcaption>3 · Turn off Follow theme, then edit</figcaption></figure></div><h2 id="bubbles" tabindex="-1">Bubbles <a class="header-anchor" href="#bubbles" aria-label="Permalink to &quot;Bubbles&quot;">​</a></h2><p><strong>Bubble</strong> and <strong>Input</strong> each have <strong>Follow theme</strong>. On uses the current theme. Off lets the settings below override the theme; empty colors still use the theme.</p><ol><li><strong>AI bubble</strong> and <strong>Your bubble</strong>: the picker is a color wheel. Preset colors are circles and show a check when selected. Opacity and the color value can be edited, and the value can be copied. A row that says “Use theme color” still follows the theme.</li><li><strong>Corner radius</strong>: higher values are rounder. After you drag, this number is used instead of the theme spacing.</li><li>Text colors are separate: <ul><li><strong>Narration text</strong> and <strong>Narration background</strong>: plain text and bold</li><li><strong>Action</strong>: text wrapped in <code>*asterisks*</code></li><li><strong>Speech</strong>: text in quotes</li><li><strong>Inner thought</strong></li></ul></li><li>If a card does not use those marks, the words still show, with the narration style. Full HTML cards keep their own colors.</li></ol><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><p>Turn off the input’s own <strong>Follow theme</strong> to change background, corner radius, placeholder, text, button icons, and <strong>Blur</strong>.</p><p>With blur on, tint and intensity can be adjusted. Android below API 31 has no blur switch. On iOS, blur starts on after you turn Follow theme off.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><p><strong>Preview</strong> at the top right opens a sample: the background is the female sample card for the current language, with a sample dialogue and the input bar. The last message is from the AI and shows continue and smart-reply buttons, but they do not send. The input cannot send either. The left button and the settings button do nothing.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./chat">Chat</a>: bubble menu and per-chat settings</li><li><a href="./settings">Settings</a>: theme and font</li></ul>',15)])])}const w=o(l,[["render",u]]);export{f as __pageData,w as default};
